CREATE TABLE "RestaurantCategory" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "RestaurantCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RestaurantProduct" ("id" TEXT NOT NULL,"categoryId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"imageUrl" TEXT,"priceCents" INTEGER NOT NULL,"costCents" INTEGER,"sku" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"trackStock" BOOLEAN NOT NULL DEFAULT true,"stockQty" INTEGER NOT NULL DEFAULT 0,"minStockQty" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RestaurantProduct_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RestaurantProduct_sku_key" ON "RestaurantProduct"("sku"); CREATE INDEX "RestaurantProduct_categoryId_active_idx" ON "RestaurantProduct"("categoryId","active");
CREATE TABLE "RestaurantOrder" ("id" TEXT NOT NULL,"bookingId" TEXT,"guestName" TEXT NOT NULL,"roomLabel" TEXT,"phone" TEXT,"status" TEXT NOT NULL DEFAULT 'NEW',"paymentMethod" TEXT NOT NULL DEFAULT 'ROOM',"paymentStatus" TEXT NOT NULL DEFAULT 'PENDING',"subtotalCents" INTEGER NOT NULL,"totalCents" INTEGER NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RestaurantOrder_pkey" PRIMARY KEY ("id"));
CREATE INDEX "RestaurantOrder_status_createdAt_idx" ON "RestaurantOrder"("status","createdAt"); CREATE INDEX "RestaurantOrder_bookingId_idx" ON "RestaurantOrder"("bookingId");
CREATE TABLE "RestaurantOrderItem" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"productId" TEXT NOT NULL,"nameSnapshot" TEXT NOT NULL,"unitPriceCents" INTEGER NOT NULL,"unitCostCents" INTEGER,"quantity" INTEGER NOT NULL,"totalCents" INTEGER NOT NULL,CONSTRAINT "RestaurantOrderItem_pkey" PRIMARY KEY ("id"));
CREATE INDEX "RestaurantOrderItem_orderId_idx" ON "RestaurantOrderItem"("orderId"); CREATE INDEX "RestaurantOrderItem_productId_idx" ON "RestaurantOrderItem"("productId");
CREATE TABLE "RestaurantStockMovement" ("id" TEXT NOT NULL,"productId" TEXT NOT NULL,"type" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"reason" TEXT,"orderId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RestaurantStockMovement_pkey" PRIMARY KEY ("id"));
CREATE INDEX "RestaurantStockMovement_productId_createdAt_idx" ON "RestaurantStockMovement"("productId","createdAt");
ALTER TABLE "RestaurantProduct" ADD CONSTRAINT "RestaurantProduct_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "RestaurantCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RestaurantOrderItem" ADD CONSTRAINT "RestaurantOrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "RestaurantOrder"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RestaurantOrderItem" ADD CONSTRAINT "RestaurantOrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "RestaurantProduct"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RestaurantStockMovement" ADD CONSTRAINT "RestaurantStockMovement_productId_fkey" FOREIGN KEY ("productId") REFERENCES "RestaurantProduct"("id") ON DELETE CASCADE ON UPDATE CASCADE;